@Component("catalog-entity-projector")
public class CatalogEntityProjector implements EntityProjector<Catalog>{
		
	// core constructor
	public CatalogEntityProjector(ProjectorRegistry registry,
										CatalogRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Catalog> getEntityClass() {
		return Catalog.class;
	}

    /*
	 * Insert a Catalog
	 * 
     * @param	entity Catalog
     */
    public Catalog create( Catalog entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Catalog
	 * 
     * @param	entity Catalog
     */
    public Catalog update( Catalog entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Catalog
	 * 
     * @param	id		UUID
     */
    public Catalog delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Catalog entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Channel
     * 
     * @param	parentId	UUID
     * @param	assignment 	Channel 
     * @return	Catalog
     */
    public Catalog assignChannel( UUID parentId, Channel assignment ) {
	    LOGGER.info("assigning Channel as " + assignment.toString() );

	    Catalog parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Channel.class, assignment.getChannelId());

	    // ------------------------------------------
		// assign the Channel to the parent entity
		// ------------------------------------------ 
	    parentEntity.setChannel( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Channel
	 * 
	 * @param	parentId		UUID
	 * @return	Catalog
	 */
	public Catalog unAssignChannel( UUID parentId ) {
		Catalog parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Channel on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Channel on the parent entithy
		// ------------------------------------------     
	    parentEntity.setChannel(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Categories
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Catalog
     */
    public Catalog addToCategories( UUID parentId, Category addTo ) {
	    LOGGER.info("handling AssignCategoriesToCatalogEvent - " );
	    
	    Catalog parentEntity = repository.findById(parentId).get();
	    Category child = registry.project( Category.class, addTo.getCategoryId());
	    
	    parentEntity.getCategories().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Categories
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Catalog
     */
	public Catalog removeFromCategories( UUID parentId, Category removeFrom ) {
	    LOGGER.info("handling RemoveCategoriesFromCatalogEvent " );
	
	    Catalog parentEntity = repository.findById(parentId).get();
	    Category child = registry.project( Category.class, removeFrom.getCategoryId());
	    
	    parentEntity.getCategories().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Catalog via an FindCatalogQuery
     * @return 	query	FindCatalogQuery
     */
    @SuppressWarnings("unused")
    public Catalog find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Catalog - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Catalogs
     *
     * @param	query	FindAllCatalogQuery 
     * @return 	List<Catalog> 
     */
    @SuppressWarnings("unused")
    public List<Catalog> findAll( FindAllCatalogQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Catalog - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final CatalogRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(CatalogEntityProjector.class.getName());

}
